// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"proof-of-stake":{"slug":"proof-of-stake","cat":"basics","en":"Proof of stake (PoS)","contentLocale":"zh-Hans","term":"权益证明（PoS）","aka":["PoS","Proof of Stake","股权证明"],"short":"权益证明（PoS）是一种共识机制，验证者通过质押代币获得出块和验证资格，作恶会被罚没质押，以太坊自 2022 年起采用。","body":[["PoS 不靠",["算力","hash-rate"],"竞争，而是让持币者把代币锁定作为“押金”，成为",["验证者","validator"],"。网络按一定规则选出验证者提议和确认新区块，表现正常就能获得奖励，离线会少拿奖励，双重签名等恶意行为则会被罚没（Slashing）一部分",["质押","staking"],"。"],[["以太坊","ethereum"],"在 2022 年 9 月通过“合并”从 ",["PoW","proof-of-work"]," 转为 PoS，能耗大幅下降。Solana、Cardano、Avalanche 等公链也使用各种 PoS 变体。不同链对最低质押量、解锁等待时间和奖励规则的设计差别很大。"],["普通用户不必自己运行",["节点","node"],"，也可以通过交易所的质押产品、委托给验证者或使用流动性质押协议参与。参与方式越省事，通常要承担的平台或合约风险越多，收益率也会随网络总质押量浮动。"]],"example":"假设某条 PoS 链的年化质押奖励约为 4%，你质押了 10 ETH。一年下来，按 4% 计算大约获得 0.4 ETH 奖励。若 ETH 价格从 3,000 USDT 跌到 2,400 USDT，你的 10.4 ETH 价值约 24,960 USDT，仍低于最初的 30,000 USDT。质押奖励按币计算，抵消不了币价下跌。","mistakes":["以为质押收益是固定利息，其实奖励率会随全网质押量和链上活动变化。","没注意解除质押需要排队或等待期，急用钱时无法立即取回。","只看收益率，不了解托管平台或流动性质押合约本身的风险。"],"faq":[{"q":"PoS 比 PoW 更安全吗？","a":"两者的安全假设不同：PoW 依赖算力成本，PoS 依赖质押资金和罚没机制。大型网络在各自机制下都已长期运行，很难简单说谁更安全。"},{"q":"我在交易所质押算参与 PoS 吗？","a":"算间接参与。交易所替你运行或委托验证者，你获得分配后的奖励，但资产由交易所托管，需要承担平台风险。"}],"title":"什么是权益证明（PoS）？含义与原理","description":"权益证明（PoS）是什么？讲清验证者如何靠质押出块、罚没机制怎么运作、以太坊为何转向 PoS，以及普通人如何参与质押。","related":[["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"],["liquid-staking","流动性质押（Liquid Staking）","流动性质押是把代币交给质押协议进行质押，同时获得一个可交易的凭证代币（如 stETH），让你在赚取质押奖励的同时仍能使用这部分资产。"],["proof-of-work","工作量证明（PoW）","工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。"],["validator","验证者（Validator）","验证者是权益证明区块链上质押代币、负责提议和验证新区块的节点运营者，正常工作获得奖励，违规会被罚没质押。"],["ethereum","以太坊（Ethereum，ETH）","以太坊是支持智能合约的开源区块链，原生币为 ETH，用于支付 Gas 费和质押，DeFi、NFT 和大量代币都运行在它上面。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"volatility":{"slug":"volatility","cat":"basics","en":"Volatility","contentLocale":"zh-Hans","term":"波动率（Volatility）","aka":["Volatility","波动性","波动"],"short":"波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。","body":[["波动率一般用价格收益率的标准差来计算，并换算成年化数值。通俗地说，一个币如果经常一天涨跌 5% 以上，它的波动率就很高；",["稳定币","stablecoin"],"理论上锚定 1 美元，波动率接近零。"],["高波动意味着机会和风险同时放大。对",["杠杆交易","margin-trading"],"来说，波动率直接决定被",["强平","liquidation"],"（爆仓）的可能：同样 10 倍",["杠杆","leverage"],"，价格日内波动 3% 的币和波动 15% 的币风险完全不同。小",["市值","market-capitalization"],"币的波动往往远高于 ",["BTC","bitcoin"],"、ETH。"],"控制波动带来的风险，常用的是仓位管理和止损：根据币种的平均波动幅度设置止损距离，再倒推应该买多少，而不是固定买一个金额。波动率也是期权定价的核心参数。"],"example":"假设 BTC 的日均波动约 3%，某小币日均波动约 12%。你用 10 倍杠杆开多，未计费用时价格反向约 10% 就会接近强平。对 BTC 来说，这相当于三个多“平均日”的波动；对小币来说，一个平常的交易日就可能触发。若你打算每笔最多亏 100 USDT、止损设在 12%，小币仓位最多约 833 USDT。","mistakes":["对所有币用同样的杠杆和止损距离，没考虑波动差异。","把稳定币也当成完全没有波动，忽视了脱锚风险。","在高波动时段用市价单大额下单，承受额外滑点。"],"faq":[{"q":"加密货币为什么波动这么大？","a":"市场规模相对较小、24 小时交易、杠杆使用普遍、消息驱动明显，这些因素叠加使价格变化比传统资产剧烈。"},{"q":"波动率高是好事还是坏事？","a":"取决于你的策略和风险承受能力。高波动带来更大的潜在收益，也意味着更大的回撤和更高的爆仓风险。"}],"title":"什么是波动率？加密货币波动的含义与风险","description":"波动率是什么意思？讲清加密货币波动率怎么理解、为什么它决定杠杆爆仓风险，以及如何根据波动设置止损和仓位大小。","related":[["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"stop-limit-order":{"slug":"stop-limit-order","cat":"trading","en":"Stop-limit order","contentLocale":"zh-Hans","term":"止损限价单（Stop-Limit Order）","aka":["Stop-limit","止损限价","计划委托"],"short":"止损限价单是包含触发价和限价两个价格的条件单，价格达到触发价后，系统以你设定的限价挂出一笔限价单。","body":[["普通",["止损单","stop-loss"],"触发后以市价成交，止损限价单则在触发后提交一笔",["限价单","limit-order"],"。你需要设置两个价格：触发价（Stop）决定何时激活订单，限价（Limit）决定最差能接受的",["成交价","last-price"],"。"],"这样做的好处是控制成交价格，避免急跌时市价止损以极差的价格成交；坏处是价格如果直接跳过你的限价，订单可能完全不成交，你的仓位就没被保护，亏损继续扩大。",["常见做法是把限价设在触发价之外留一点空间，比如卖出止损触发价 100、限价 99.5，提高成交概率。各",["交易所","centralized-exchange"],"对这类订单的叫法不同，有的叫“计划委托”或“条件单”，触发价可选最新价或",["标记价格","mark-price"],"。"]],"example":["假设你持有 10 枚某币，现价 50 ",["USDT","usdt"],"。你设止损限价单：触发价 46，限价 45.5。价格跌到 46 时，系统挂出 45.5 的限价卖单。如果价格缓慢下跌，订单在 45.5 到 46 之间成交，亏损约 40 到 45 USDT。但如果一根大阴线从 46.2 直接跳到 43，订单挂在 45.5 无人接，你仍持有 10 枚，浮亏变成 70 USDT。"],"mistakes":["把触发价和限价设成同一个数，急跌时几乎一定不成交。","以为止损限价单和市价止损一样保证离场。","设置后不检查是否成交，以为已经止损出局。"],"faq":[{"q":"止损限价单和止损市价单有什么区别？","a":"止损市价单触发后必定以市价成交但价格不确定；止损限价单能控制成交价格，但可能不成交。"},{"q":"什么时候适合用止损限价单？","a":"在流动性较好、价格不容易跳空的交易对上，或者你更在意成交价格而非确定离场时比较适合。"}],"title":"什么是止损限价单？触发价与限价的含义","description":"止损限价单是什么？讲清触发价和限价如何设置、与市价止损的区别、为什么急跌时可能不成交，以及设置时留出价格缓冲的方法。","related":[["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"],["trailing-stop","移动止损（Trailing Stop）","移动止损是一种会随价格朝有利方向移动而自动跟进的止损单，以固定比例或金额保持与最高价（或最低价）的距离，价格回撤到该距离时触发。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"止盈止损，是计划，不是保险"},"coin":null,"tool":null,"cta":false},"time-in-force":{"slug":"time-in-force","cat":"trading","en":"Time in force (GTC, IOC, FOK)","contentLocale":"zh-Hans","term":"订单有效期（GTC、IOC、FOK）","aka":["Time in force","GTC","IOC","FOK"],"short":"订单有效期（Time in Force）规定了一笔订单在未成交时保留多久以及如何处理未成交部分，常见选项有 GTC、IOC 和 FOK。","body":[["GTC（Good Till Cancelled，一直有效直到取消）：订单会一直挂在",["订单簿","order-book"],"上，直到全部成交或你手动撤单。这是大多数",["交易所","centralized-exchange"],["限价单","limit-order"],"的默认设置，部分平台对长期未成交订单可能有自动清理规则。"],"IOC（Immediate Or Cancel，立即成交或取消）：订单提交后立即尽可能成交，能成交多少算多少，剩余部分马上取消，不会挂在订单簿上。FOK（Fill Or Kill，全部成交或全部取消）：订单必须立即全部成交，否则整笔取消，不允许部分成交。",["IOC 和 FOK 都不会成为挂单，因此通常按",["吃单费","maker-taker-fees"],"率收费。它们适合想控制价格、又不想留下挂单的场景，比如大额交易时只吃到某个价位为止。不同交易所支持的选项和名称略有差异。"]],"example":["假设订单簿卖方在 10.00 ",["USDT","usdt"]," 挂了 300 枚、10.02 挂了 500 枚。你下一个 10.00 买入 800 枚的限价单：选 GTC，300 枚立即成交，其余 500 枚挂在 10.00 等待；选 IOC，300 枚成交，其余 500 枚取消；选 FOK，因为在 10.00 无法全部买到 800 枚，整笔订单取消，一枚都不买。"],"mistakes":["选了 FOK 却不明白为什么订单一直被取消。","用 GTC 挂单后忘记撤单，很久以后在不想要的价格成交。","以为 IOC 会挂单等待，结果未成交部分直接消失。"],"faq":[{"q":"GTC、IOC、FOK 应该选哪个？","a":"想挂单等价格到位选 GTC；想马上成交、能买多少算多少选 IOC；必须一次全部成交否则不做选 FOK。"},{"q":"交易所默认用哪种？","a":"多数交易所的限价单默认是 GTC，高级下单界面里可以切换为 IOC 或 FOK。"}],"title":"订单有效期是什么？GTC、IOC、FOK 的区别","description":"GTC、IOC、FOK 分别是什么意思？用订单簿例子讲清三种订单有效期如何处理未成交部分，以及各自适合的交易场景。","related":[["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["post-only-order","只做挂单（Post-Only）","只做挂单（Post-Only）是一种限价单选项，保证订单只以挂单（Maker）身份进入订单簿，如果会立即成交为吃单就自动取消或调整。"],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"市价、限价、撤单，分别解决什么问题？"},"coin":null,"tool":null,"cta":false},"private-key":{"slug":"private-key","cat":"wallets-security","en":"Private key","contentLocale":"zh-Hans","term":"私钥（Private Key）","aka":["私钥","Private key","密钥"],"short":"私钥是一串只有持有人知道的随机数字，用来对交易进行数字签名，证明你有权动用某个地址里的资产，私钥泄露就等于资产失控。","body":[[["区块链","blockchain"],"用非对称加密：私钥生成",["公钥","public-key"],"，公钥再生成",["钱包地址","wallet-address"],"。你转账时，钱包用私钥给交易签名，全网",["节点","node"],"用公钥验证签名是否有效，但无法从公钥或地址反推出私钥。"],["以",["比特币","bitcoin"],"和",["以太坊","ethereum"],"为例，私钥本质上是一个 256 位的数字，通常写成 64 位十六进制字符串。钱包软件一般不会直接让你接触私钥，而是用助记词来统一备份。"],"加密圈常说“不是你的私钥，就不是你的币”。放在交易所的资产，私钥由平台掌握；放在自托管钱包里的资产，私钥才真正在你手中，安全也全靠你自己。"],"example":"一个以太坊私钥由 64 个十六进制字符组成，每个字符有 16 种可能，总组合约为 1.16 乘以 10 的 77 次方。假设你从钱包中导出某个地址的私钥，粘贴到一个号称能“查询空投”的网站上，对方拿到后就能签名把该地址里的 3 ETH 和所有代币一次性转走，而链上交易一旦确认就无法撤回。","mistakes":["以为私钥和交易所登录密码一样，忘了还能重置。","为了“导入钱包”把私钥发给自称客服或技术支持的人。","把私钥复制到剪贴板后不清理，被恶意软件读取。"],"faq":[{"q":"私钥和公钥有什么区别？","a":"私钥必须保密，用来签名；公钥可以公开，用来验证签名并生成地址。由私钥能算出公钥，反过来则不可行。"},{"q":"私钥可以修改吗？","a":"私钥本身不能修改。如果怀疑泄露，唯一办法是新建钱包，把资产尽快转到新地址。"}],"title":"什么是私钥？加密货币私钥的含义与作用","description":"私钥是什么意思？了解私钥如何签名交易、与公钥和钱包地址的关系，为什么私钥泄露无法补救，以及保管私钥时的常见错误。","related":[["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。"],["public-key","公钥（Public Key）","公钥是由私钥通过数学运算得出、可以公开的密钥，网络用它来验证交易签名是否由对应私钥签出，钱包地址也是由公钥进一步计算得来的。"],["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["multisig-wallet","多签钱包（Multisig Wallet）","多签钱包是需要多把私钥中的若干把共同签名才能转出资产的钱包，例如“3 选 2”，常用于团队资金、DAO 金库和大额个人资产管理。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"amm":{"slug":"amm","cat":"defi","en":"Automated market maker (AMM)","contentLocale":"zh-Hans","term":"自动做市商（AMM）","aka":["AMM","自动做市商","Automated market maker"],"short":"自动做市商（AMM）是一种用流动性池和数学公式自动给代币定价的交易机制，不需要买卖双方挂单撮合，是 Uniswap 等去中心化交易所的核心。","body":[["传统",["交易所","centralized-exchange"],"靠",["订单簿","order-book"],"：有人挂买单、有人挂卖单，价格在撮合中形成。AMM 则把两种代币放进一个",["流动性池","liquidity-pool"],"，由公式决定价格。最经典的是恒定乘积公式 x 乘以 y 等于 k：池里一种代币变少，它的价格就自动变贵。"],[["流动性","liquidity"],"由普通用户（流动性提供者，LP）存入，他们按比例分享交易手续费，同时承担",["无常损失","impermanent-loss"],"。交易者随时都能成交，但",["交易量","trading-volume"],"相对池子越大，价格偏离越多，也就是滑点越大。"],"后来出现了集中流动性（如 Uniswap v3）、稳定币专用曲线（如 Curve）等改进，目的是让同样的资金提供更深的流动性。"],"example":"假设一个池子里有 100 ETH 和 300,000 USDC，ETH 价格为 3,000 USDC，k 等于 3,000 万。你投入 30,000 USDC 买 ETH（忽略手续费），池中 USDC 变为 330,000，ETH 变为 3,000 万除以 33 万，约 90.91 枚，你拿到约 9.09 ETH，平均成交价约 3,300 USDC，比初始价格高了约 10%，这就是大额交易在小池子里的滑点。","mistakes":["以为 AMM 的报价就是“市场价”，忽略了自己的交易量会推动价格。","在流动性很浅的池子里一次性大额买入。","把提供流动性当成无风险存款，不了解无常损失。"],"faq":[{"q":"AMM 和订单簿有什么区别？","a":"订单簿需要有人挂单才能成交，价格由买卖双方决定；AMM 用资金池和公式即时报价，任何时候都能成交，但大额交易滑点明显。"},{"q":"AMM 的价格会不会和交易所差很多？","a":"如果偏离过大，套利者会在两边低买高卖，把价格拉回接近的水平，所以主流池子的价格一般与中心化交易所接近。"}],"title":"什么是 AMM？自动做市商原理与恒定乘积公式","description":"AMM 自动做市商是什么？用一个计算例子讲清恒定乘积公式如何定价、为什么大额交易会产生滑点，以及 LP 要承担的风险。","related":[["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"],["impermanent-loss","无常损失（Impermanent Loss）","无常损失是指你在 AMM 流动性池中提供流动性时，因两种代币价格比例变化，导致取回资产的价值低于单纯持有这些代币所造成的差额。"],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"staking":{"slug":"staking","cat":"defi","en":"Staking","contentLocale":"zh-Hans","term":"质押（Staking）","aka":["质押","Staking","锁仓质押","质押挖矿"],"short":"质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。","body":[["在",["以太坊","ethereum"],"、Solana 等 ",["PoS","proof-of-stake"]," 网络中，",["验证者","validator"],"需要质押代币作为保证，按规则出块和投票，就能获得新发行的代币和部分交易费；如果作恶或长时间离线，可能被罚没（Slashing）部分质押。以太坊在 2022 年 9 月合并后转为权益证明。"],["普通用户参与方式大致有三种：自己运行",["节点","node"],"（以太坊要求 32 ETH 和一定技术能力）、委托给验证者，或使用",["交易所","centralized-exchange"],"的质押/赚币产品和",["流动性质押","liquid-staking"],"协议。后两者门槛低，但要支付服务费并承担平台或合约风险。"],"需要注意锁定期和解押时间：有的网络退出质押需要排队，交易所产品也可能有赎回期。收益率随网络参与情况浮动，具体以各平台页面实时显示为准。"],"example":"假设你质押 20 SOL，网络年化收益率约为 6%，验证者收取 10% 佣金，你的实际年化约为 6% 乘以 90%，即 5.4%。一年后大约多出 1.08 SOL。但收益以 SOL 计算，如果这一年 SOL 价格下跌 30%，即使币数增加，以美元计算的总价值仍可能下降。","mistakes":["只看币本位收益率，忽略了代币本身价格的波动。","急用钱时才发现解押需要排队或有赎回期。","把质押给了来历不明的平台或“高息质押”网站。"],"faq":[{"q":"质押的币会丢吗？","a":"正常情况下本金不会减少，但可能因验证者被罚没、平台出问题或合约漏洞而受损。自己选择的验证者和平台的可靠性很重要。"},{"q":"交易所质押和链上质押有什么区别？","a":"交易所质押操作简单，由平台代为运行节点并托管资产；链上质押由你自己的钱包完成，资产自托管，但需要了解操作流程和解押规则。"}],"title":"什么是质押（Staking）？质押收益怎么来","description":"质押 Staking 是什么意思？了解 PoS 质押如何获得奖励、自建节点与交易所质押的区别、罚没和解押等待期，以及收益计算方法。","related":[["proof-of-stake","权益证明（PoS）","权益证明（PoS）是一种共识机制，验证者通过质押代币获得出块和验证资格，作恶会被罚没质押，以太坊自 2022 年起采用。"],["liquid-staking","流动性质押（Liquid Staking）","流动性质押是把代币交给质押协议进行质押，同时获得一个可交易的凭证代币（如 stETH），让你在赚取质押奖励的同时仍能使用这部分资产。"],["validator","验证者（Validator）","验证者是权益证明区块链上质押代币、负责提议和验证新区块的节点运营者，正常工作获得奖励，违规会被罚没质押。"],["crypto-earn","理财/赚币（Crypto Earn）","理财（赚币）是交易所提供的加密资产收益产品，把你账户里的闲置币放进活期或定期产品中，由平台通过借贷、质押或其他方式产生收益并按约定发放。"],["apr-vs-apy","APR 和 APY 的区别","APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"total-value-locked":{"slug":"total-value-locked","cat":"defi","en":"Total value locked (TVL)","contentLocale":"zh-Hans","term":"总锁仓价值（TVL）","aka":["TVL","锁仓量","总锁仓量","Total value locked"],"short":"总锁仓价值（TVL）是指存放在某个 DeFi 协议或某条公链智能合约中的资产总价值，通常以美元计算，用来衡量协议规模和资金规模。","body":[["TVL 把一个协议里所有的存款、抵押品和",["流动性池","liquidity-pool"],"资产按当前价格折算后相加。它常被用来比较不同协议或不同链的生态规模，数据平台会按协议、按链、按类别展示 TVL 排名。"],["TVL 会随币价波动：即使没人取钱，",["ETH","ethereum"]," 价格下跌也会让以 ETH 计价的锁仓价值缩水。此外，同一笔资金可能在多个协议间重复计算，例如",["质押凭证","liquid-staking"],"再被存入",["借贷协议","defi-lending"],"，导致总数被夸大。"],["TVL 高不等于安全或赚钱。看协议时还要结合",["交易量","trading-volume"],"、手续费收入、用户数和资金来源，判断资金是长期留存还是被短期高额奖励吸引而来。"]],"example":["假设某借贷协议锁仓了 20,000 ETH 和 4,000 万美元",["稳定币","stablecoin"],"，ETH 价格为 3,000 美元，TVL 为 6,000 万加 4,000 万，共 1 亿美元。如果 ETH 跌 20% 到 2,400 美元，ETH 部分变成 4,800 万，TVL 降到 8,800 万美元，下降 12%，但实际上没有任何用户取走资金。"],"mistakes":["把 TVL 当作协议安全性的证明。","看到 TVL 下降就以为资金在大量出逃，没区分币价下跌的影响。","直接把不同数据平台的 TVL 对比，忽略统计口径和重复计算的差异。"],"faq":[{"q":"TVL 和市值有什么区别？","a":"市值是代币流通量乘以价格，反映市场对代币的定价；TVL 是锁在协议里的资产价值，反映协议管理的资金规模。"},{"q":"TVL 越高的项目越好吗？","a":"不一定。TVL 可能因高额补贴短期涌入，也可能因重复计算被放大，还要看收入、用户留存和安全记录。"}],"title":"什么是 TVL？总锁仓价值的含义与局限","description":"TVL 总锁仓价值是什么意思？了解 TVL 如何计算、为何会随币价涨跌、重复计算如何夸大数据，以及评估 DeFi 协议时该怎么看。","related":[["defi","DeFi（去中心化金融）","DeFi（去中心化金融）是指运行在区块链智能合约上的金融服务，比如交易、借贷、质押和收益聚合，用户用自己的钱包直接参与，无需银行或交易所作为中介。"],["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"],["defi-lending","DeFi 借贷","DeFi 借贷是通过智能合约进行的超额抵押借贷，存款人把资产存入资金池赚利息，借款人先存入抵押品再借出其他资产，抵押不足时会被自动清算。"],["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"depeg":{"slug":"depeg","cat":"stablecoins","en":"Depeg","contentLocale":"zh-Hans","term":"脱锚（Depeg）","aka":["稳定币脱锚","Depeg","掉锚"],"short":"脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。","body":[[["稳定币","stablecoin"],"靠储备资产、超额抵押或算法机制来维持锚定。平时价格会在1美元上下极小的范围内波动，这属于正常的",["买卖价差","bid-ask-spread"],"；只有当偏离持续扩大、市场开始怀疑它能否按1美元赎回时，大家才会说它脱锚了。"],["常见诱因包括：储备资产出了问题（比如存放储备的银行出现风险）、抵押品价格暴跌、算法机制失灵，或者大量持有人同时抛售导致",["流动性","liquidity"],"枯竭。",["流动性质押","liquid-staking"],"代币（如 stETH 相对 ",["ETH","ethereum"],"）也会出现类似的折价，只是它锚定的是另一种资产而不是美元。"],["对交易者来说，脱锚的影响远不止账面亏损：用稳定币做合约保证金、放在",["借贷协议","defi-lending"],"里当抵押品、或者在流动性池里做市，价格偏离都可能引发强平（爆仓）或无常损失。不同平台对脱锚稳定币的处理也不同，有的会调整保证金折算率，有的会暂停相关交易对。"]],"example":"假设你持有10,000枚某美元稳定币，它突然跌到0.97美元，账面价值变成9,700美元，少了300美元。如果你此时在0.97美元买入10,000枚，花费9,700美元，等价格恢复到1美元就能卖得10,000美元，赚300美元；但如果发行方最终无法足额赎回，价格可能继续下跌到0.80甚至更低，这笔“抄底”就会亏损2,000美元以上。","mistakes":["以为所有稳定币风险相同，不去查看它的储备构成和赎回机制。","把全部合约保证金都放在单一稳定币上，一旦脱锚，保证金价值缩水可能直接导致强平。","看到小幅折价就重仓抄底，却没有判断脱锚原因是暂时的流动性问题还是储备真的出了问题。"],"faq":[{"q":"稳定币脱锚后一定能恢复吗？","a":"不一定。如果只是短暂的抛压，有足额储备的稳定币通常会通过赎回和套利回到1美元附近；如果储备不足或机制失灵，价格可能长期无法恢复。"},{"q":"稳定币价格是0.998算不算脱锚？","a":"一般不算。千分之几的偏离是正常的买卖价差和交易成本，只有偏离持续且明显扩大时才被视为脱锚。"}],"title":"什么是脱锚（Depeg）？稳定币脱锚的含义与风险","description":"了解稳定币脱锚是什么意思、为什么会发生、对合约保证金和DeFi仓位有什么影响，以及遇到脱锚时新手常犯的错误。","related":[["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["algorithmic-stablecoin","算法稳定币（Algorithmic stablecoin）","算法稳定币是主要依靠代码规则调节供应量、而不是靠足额现金或抵押品来维持1美元价格的稳定币，在信心崩溃时容易出现严重脱锚。"],["usdc","USDC（美元币）","USDC 是由 Circle 公司发行、与美元 1:1 挂钩的稳定币，储备主要为现金和短期美国国债，以储备披露较透明著称，在 DeFi 和合规场景中使用广泛。"],["liquid-staking","流动性质押（Liquid Staking）","流动性质押是把代币交给质押协议进行质押，同时获得一个可交易的凭证代币（如 stETH），让你在赚取质押奖励的同时仍能使用这部分资产。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT是美元吗？为什么买币常见它？"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false},"real-world-assets":{"slug":"real-world-assets","cat":"tokenized-assets","en":"Real-world assets (RWA)","contentLocale":"zh-Hans","term":"现实世界资产（RWA）","aka":["RWA","真实世界资产","资产代币化"],"short":"现实世界资产（RWA）是指被代币化后在区块链上发行和流通的链下资产，例如国债、货币市场基金、私人信贷、房地产、黄金和股票等。","body":["RWA的核心是把传统资产的权益搬到链上：发行方在链下持有或托管资产，通过法律结构（例如特殊目的公司或基金份额）把权益与链上代币绑定。这样资产可以全天候转让、按小额拆分，并能接入链上的借贷、抵押等DeFi应用。",["目前规模较大的RWA类别包括代币化美国国债和货币市场基金、私人信贷以及",["代币化黄金","tokenized-gold"],"。贝莱德的BUIDL基金和Ondo Finance的产品都是常被提到的",["代币化国债","tokenized-treasuries"],"案例。",["稳定币","stablecoin"],"从某种意义上也是最早的RWA之一，背后是现金和短期国债储备。"],"RWA的风险与加密原生资产不同：价值依赖链下资产是否真实存在、托管是否可靠、法律上代币持有人能否主张权利。很多产品只向通过KYC的合格投资者开放，赎回可能需要工作日处理，并受发行地法规约束。"],"example":["假设某代币化私人信贷产品的底层贷款年化收益为5%，管理费等成本为每年0.5%，投资者净收益约4.5%。你投入10,000 ",["USDC","usdc"],"，一年预期净收益约450 USDC。但如果底层借款人中有占资金10%的贷款违约且无法收回，组合会损失约1,000 USDC，扣除收益后整体亏损约550 USDC。这种风险来自链下资产本身，而不是",["区块链","blockchain"],"技术。"],"mistakes":["以为资产上链后就消除了链下的信用、托管和法律风险。","只看收益率，不核查底层资产、托管机构和审计报告。","忽视产品的KYC、地区限制和赎回时间，以为可以像普通代币一样随时变现。"],"faq":[{"q":"RWA是什么意思？","a":"RWA是Real-World Assets的缩写，指国债、黄金、信贷、房地产等现实世界资产通过代币化在区块链上发行和交易。"},{"q":"RWA代币安全吗？","a":"安全性主要取决于链下资产的质量、托管和法律结构，以及智能合约本身的安全，需要分别核查，而不是只看是否上链。"}],"title":"什么是RWA现实世界资产？代币化原理与风险","description":"RWA现实世界资产是什么？了解国债、黄金、私人信贷等资产如何代币化上链，收益来源、法律结构以及链下信用和托管风险。","related":[["tokenized-treasuries","代币化美债（Tokenized treasuries）","代币化美债是把美国短期国债或投资国债的货币市场基金份额以代币形式发行到区块链上的产品，持有者可以在链上获得接近国债利率的收益。"],["tokenized-stocks","代币化股票（Tokenized stocks）","代币化股票是把上市公司股票的价格和经济权益映射到区块链代币上的产品，通常由发行方托管真实股票并按1:1发行代币，可在交易所或链上交易。"],["tokenized-gold","代币化黄金（Tokenized gold）","代币化黄金是由发行方在金库中托管实物黄金、并按固定比例在区块链上发行的代币，例如1枚PAXG或XAUT对应1金衡盎司黄金，价格跟随金价变动。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-assets","cta":false}});
